def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    out = [r[:] for r in grid]
    bg = Counter(x for r in grid for x in r).most_common(1)[0][0]

    barriers = [r for r in range(h) if sum(x != bg for x in grid[r]) > w // 2]
    gates = []
    for r in barriers:
        row = grid[r]
        barrier_color = Counter(row).most_common(1)[0][0]
        openings = [c for c in range(w) if row[c] != barrier_color]
        gates.append((r, (min(openings) + max(openings)) // 2))

    dots = []
    for r in range(h):
        if r in barriers:
            continue
        for c in range(w):
            if grid[r][c] != bg:
                dots.append((r, c, grid[r][c]))
    color = dots[0][2]
    nodes = sorted([(r, c) for r, c, _ in dots] + gates)

    for i, ((r0, c0), (r1, c1)) in enumerate(zip(nodes, nodes[1:])):
        last = i == len(nodes) - 2
        for r in range(r0, r1):
            out[r][c0] = color
        if not last:
            out[r1][c1] = color
        tr = r1 if last else r1 - 1
        if c1 >= c0:
            for c in range(c0, c1 + 1):
                out[tr][c] = color
        else:
            for c in range(c1 - 1, c0 + 1):
                if 0 <= c < w:
                    out[tr][c] = color
    return out
